<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --panel: rgba(255, 255, 255, 0.88);
        --panel-solid: #ffffff;
        --text: #162033;
        --muted: #667085;
        --border: rgba(18, 32, 64, 0.1);
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
        --primary: #2563eb;
        --primary-hover: #1d4ed8;
        --danger: #dc2626;
        --danger-hover: #b91c1c;
        --overlay: rgba(15, 23, 42, 0.58);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 32%),
          radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.12), transparent 28%),
          var(--bg);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px;
      }

      .preview-card {
        width: min(100%, 760px);
        background: var(--panel);
        backdrop-filter: blur(16px);
        border: 1px solid var(--border);
        border-radius: 28px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .preview-media {
        aspect-ratio: 16 / 10;
        background:
          linear-gradient(135deg, rgba(37, 99, 235, 0.2), rgba(14, 165, 233, 0.08)),
          #dbeafe;
        position: relative;
      }

      .preview-media img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
      }

      .preview-body {
        padding: 24px;
        display: grid;
        gap: 16px;
      }

      .preview-meta h1 {
        margin: 0 0 8px;
        font-size: clamp(1.4rem, 2vw, 2rem);
        line-height: 1.15;
      }

      .preview-meta p {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button {
        font: inherit;
      }

      .delete-btn,
      .secondary-btn,
      .primary-btn {
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.25rem;
        font-weight: 600;
        cursor: pointer;
        transition: transform 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
      }

      .delete-btn {
        background: rgba(220, 38, 38, 0.1);
        color: var(--danger);
      }

      .delete-btn:hover {
        background: rgba(220, 38, 38, 0.16);
      }

      .delete-btn:active,
      .secondary-btn:active,
      .primary-btn:active {
        transform: translateY(1px);
      }

      dialog {
        width: min(92vw, 440px);
        border: 1px solid rgba(255, 255, 255, 0.2);
        border-radius: 24px;
        padding: 0;
        background: var(--panel-solid);
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: var(--overlay);
        backdrop-filter: blur(6px);
      }

      .modal {
        padding: 24px;
      }

      .modal h2 {
        margin: 0 0 8px;
        font-size: 1.35rem;
      }

      .modal p {
        margin: 0;
        color: var(--muted);
        line-height: 1.6;
      }

      .modal-actions {
        margin-top: 24px;
        display: flex;
        justify-content: flex-end;
        gap: 12px;
      }

      .secondary-btn {
        background: #eef2ff;
        color: var(--text);
      }

      .secondary-btn:hover {
        background: #e0e7ff;
      }

      .primary-btn {
        background: var(--danger);
        color: white;
        box-shadow: 0 12px 28px rgba(220, 38, 38, 0.2);
      }

      .primary-btn:hover {
        background: var(--danger-hover);
      }

      .trigger:focus-visible,
      .secondary-btn:focus-visible,
      .primary-btn:focus-visible {
        outline: 3px solid rgba(37, 99, 235, 0.28);
        outline-offset: 2px;
      }

      @media (max-width: 640px) {
        .page {
          padding: 16px;
        }

        .preview-body,
        .modal {
          padding: 18px;
        }

        .actions,
        .modal-actions {
          flex-direction: column;
        }

        .actions {
          align-items: stretch;
        }

        .modal-actions button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <article class="preview-card" aria-label="Image preview">
        <div class="preview-media">
          <img
            src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
            alt="Modern workspace with a laptop, coffee, and notebook"
          />
        </div>
        <div class="preview-body">
          <div class="preview-meta">
            <h1>Workspace Snapshot</h1>
            <p>Review the image before removing it from your library.</p>
          </div>
          <div class="actions">
            <button class="delete-btn trigger" type="button" id="openDialog">
              Delete image
            </button>
          </div>
        </div>
      </article>
    </main>

    <dialog id="confirmDialog" aria-labelledby="dialogTitle" aria-describedby="dialogDescription">
      <div class="modal">
        <h2 id="dialogTitle">Delete this image?</h2>
        <p id="dialogDescription">
          This will permanently remove the image from your library. This action cannot be undone.
        </p>
        <div class="modal-actions">
          <button class="secondary-btn" type="button" id="cancelDelete">Cancel</button>
          <button class="primary-btn" type="button" id="confirmDelete">Delete</button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("confirmDialog");
      const openDialogButton = document.getElementById("openDialog");
      const cancelButton = document.getElementById("cancelDelete");
      const confirmButton = document.getElementById("confirmDelete");

      openDialogButton.addEventListener("click", () => {
        dialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close();
      });

      confirmButton.addEventListener("click", () => {
        dialog.close();
        openDialogButton.textContent = "Deleted";
        openDialogButton.disabled = true;
      });

      dialog.addEventListener("click", (event) => {
        const rect = dialog.getBoundingClientRect();
        const clickedOutside =
          event.clientX < rect.left ||
          event.clientX > rect.right ||
          event.clientY < rect.top ||
          event.clientY > rect.bottom;

        if (clickedOutside) {
          dialog.close();
        }
      });
    </script>
  </body>
</html>
