       .secondary-btn {
         background: #eef2ff;
         color: var(--text);
       }

       .secondary-btn:hover {
         background: #e0e7ff;
       }

       .primary-btn {
         background: var(--danger);
         color: white;
         box-shadow: 0 12px 28px rgba(220, 38, 38, 0.2);
       }

       .primary-btn:hover {
         background: var(--danger-hover);
       }

       .trigger:focus-visible,
       .secondary-btn:focus-visible,
       .primary-btn:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.28);
         outline-offset: 2px;
       }

       @media (max-width: 640px) {
         .page {
           padding: 16px;
         }

         .preview-body,
         .modal {
           padding: 18px;
         }

         .actions,
         .modal-actions {
           flex-direction: column;
         }

         .actions {
           align-items: stretch;
         }

         .modal-actions button {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <main class="page">
       <article class="preview-card" aria-label="Image preview">
         <div class="preview-media">
           <img
             src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
             alt="Modern workspace with a laptop, coffee, and notebook"
           />
         </div>
         <div class="preview-body">
           <div class="preview-meta">
             <h1>Workspace Snapshot</h1>
             <p>Review the image before removing it from your library.</p>
           </div>
           <div class="actions">
             <button class="delete-btn trigger" type="button" id="openDialog">
               Delete image
             </button>
           </div>
         </div>
       </article>
     </main>

     <dialog id="confirmDialog" aria-labelledby="dialogTitle" aria-describedby="dialogDescription">
       <div class="modal">
         <h2 id="dialogTitle">Delete this image?</h2>
         <p id="dialogDescription">
           This will permanently remove the image from your library. This action cannot be undone.
         </p>
         <div class="modal-actions">
           <button class="secondary-btn" type="button" id="cancelDelete">Cancel</button>
           <button class="primary-btn" type="button" id="confirmDelete">Delete</button>
         </div>
       </div>
     </dialog>

     <script>
       const dialog = document.getElementById("confirmDialog");
       const openDialogButton = document.getElementById("openDialog");
       const cancelButton = document.getElementById("cancelDelete");
       const confirmButton = document.getElementById("confirmDelete");

       openDialogButton.addEventListener("click", () => {
         dialog.showModal();
       });

       cancelButton.addEventListener("click", () => {
         dialog.close();
       });

       confirmButton.addEventListener("click", () => {
         dialog.close();
         openDialogButton.textContent = "Deleted";
         openDialogButton.disabled = true;
       });

       dialog.addEventListener("click", (event) => {
         const rect = dialog.getBoundingClientRect();
         const clickedOutside =
           event.clientX < rect.left ||
           event.clientX > rect.right ||
           event.clientY < rect.top ||
           event.clientY > rect.bottom;

         if (clickedOutside) {
           dialog.close();
         }
       });
     </script>
   </body>
 </html>

')
